"""Synthetic public fixtures only. Fake tools prove orchestration, never EIFs."""
import copy
import errno
import importlib.util
import json
import os
from pathlib import Path
import shutil
import signal
import subprocess
import tempfile
import time
import unittest
from unittest.mock import patch

HERE = Path(__file__).resolve().parent
spec = importlib.util.spec_from_file_location('dual', HERE / 'build-dual-enclave.py')
dual = importlib.util.module_from_spec(spec)
spec.loader.exec_module(dual)
# Public P-256 generator point; no private key is used/generated by this suite.
POINT = '046b17d1f2e12c4247f8bce6e563a440f277037d812deb33a0f4a13945d898c2964fe342e2fe1a7f9b8ee7eb4a7c0f9e162bce33576b315ececbb6406837bf51f5'
ARN = 'arn:aws:kms:us-east-1:123456789012:key/11111111-2222-3333-4444-555555555555'

# Executable Docker/Nitro surrogate. Its persisted container inventory models a
# daemon-side create surviving the client that lost the reply. No daemon is used.
CREATE_TOOL = r'''#!/usr/bin/python3
import json, pathlib, shutil, sys, time
root = pathlib.Path(__file__).parent
cfg = json.loads((root / 'settings.json').read_text())
state_path = root / 'containers.json'
state = json.loads(state_path.read_text())
args = sys.argv[1:]
if args[:1] == ['--host']: args = args[2:]
with (root / 'calls.jsonl').open('a') as stream:
    stream.write(json.dumps(args) + '\n')
mode = cfg['mode']
if args[:2] in (['buildx', 'create'], ['buildx', 'build'], ['buildx', 'stop'], ['buildx', 'rm'], ['image', 'rm']):
    pass
elif args[:2] == ['image', 'inspect']:
    if '{{.Id}}' in args: print('sha256:' + 'a' * 64)
    else:
        mapping = (pathlib.Path(cfg['context']) / 'public/network-profiles.json').read_text()
        print(json.dumps(['NODE_ENV=production', 'MORPHEUS_ATTESTED_BOOT=require', 'MORPHEUS_ALLOW_EPHEMERAL_KEY=0', 'MORPHEUS_NETWORK_PROFILES_JSON=' + mapping]))
elif args[:1] == ['create']:
    name = args[args.index('--name') + 1] if '--name' in args else 'untracked'
    labels = dict([args[args.index('--label') + 1].split('=', 1)]) if '--label' in args else {}
    cid = ('b' if not (root / 'created').exists() else 'c') * 64
    item = {'Id': cid, 'Name': '/' + name, 'Image': args[-1], 'Config': {'Labels': labels}}
    if mode == 'collision':
        item['Id'] = 'e' * 64
        item['Config']['Labels'] = {key: 'foreign-owner' for key in labels}
    state[item['Id']] = item
    state_path.write_text(json.dumps(state))
    if mode == 'collision':
        (root / 'collision.json').write_text(json.dumps(item))
        sys.exit(1)
    (root / 'created').touch()
    if mode in ('timeout', 'sigterm'): time.sleep(20)
    if mode == 'error': sys.exit(1)
    if mode == 'malformed': print('unusable reply')
    elif mode == 'foreign-reply': print('d' * 64)
    else: print(cid)
elif args[:2] == ['container', 'ls']:
    name = args[args.index('--filter') + 1].split('=', 1)[1]
    for item in state.values():
        if name in item['Name']: print(item['Id'])
elif args[:2] == ['container', 'inspect']:
    item = state[args[-1]]
    print(json.dumps([item]))
    if mode == 'replacement' and (root.parent / 'build-2.eif').exists() and not (root / 'collision.json').exists():
        # A foreign container takes the same name after the ownership read.
        replacement = dict(item, Id='e' * 64, Config={'Labels': {}})
        state[replacement['Id']] = replacement
        item['Name'] += '-renamed'
        state_path.write_text(json.dumps(state))
        (root / 'collision.json').write_text(json.dumps(replacement))
elif args[:1] == ['rm']:
    if mode == 'cleanup-error': sys.exit(1)
    # Deliberately support removal by name too: tests catch unsafe cleanup.
    for cid, item in list(state.items()):
        if args[-1] in (cid, item['Name'].lstrip('/')): del state[cid]
    state_path.write_text(json.dumps(state))
elif args[:1] == ['cp']:
    assert args[-2].split(':')[0] in state, 'copy must use an existing full ID'
    dest = pathlib.Path(args[-1])
    shutil.copytree(pathlib.Path(cfg['context']) / 'public', dest)
    (dest / 'custody-build-validation.json').write_text(json.dumps({'schema': 'neoos/dual-custody-build/v1', 'networks': ['mainnet', 'testnet'], 'map_sha256': cfg['map']}))
elif args[:1] in (['build-enclave'], ['describe-eif']):
    if args[0] == 'build-enclave': pathlib.Path(args[-1]).write_bytes(b'synthetic EIF, not release evidence')
    print(json.dumps({'Measurements': {'HashAlgorithm': 'SHA384', 'PCR0': '1' * 96, 'PCR1': '2' * 96, 'PCR2': '3' * 96}}))
else: raise AssertionError(args)
'''


class Packaging(unittest.TestCase):
    def setUp(self):
        self.tmp = tempfile.TemporaryDirectory(prefix='dual-fixtures-')
        self.addCleanup(self.tmp.cleanup)
        # /var is a symlink on macOS; production paths reject symbolic aliases.
        self.root = Path(self.tmp.name).resolve()
        self.repo = self.root / 'source'; self.repo.mkdir()
        self.env = dual.safe_env(self.root / 'home')
        self.registry = {}
        for n in dual.NETWORKS:
            p = self.repo / 'config/networks' / (n + '.json'); p.parent.mkdir(parents=True, exist_ok=True)
            registry = json.loads((HERE.parent.parent / 'config/networks' / (n + '.json')).read_bytes())
            self.registry[n] = registry
            p.write_bytes(dual.encoded(registry))
        (self.repo / 'Cargo.toml').write_text('[workspace]\n')
        (self.repo / 'Cargo.lock').write_text('version = 4\n')
        (self.repo / 'deploy/nitro').mkdir(parents=True)
        shutil.copyfile(HERE / 'Dockerfile.dual-enclave', self.repo / 'deploy/nitro/Dockerfile.dual-enclave')
        shutil.copyfile(HERE / 'dual-prepare.rs', self.repo / 'deploy/nitro/dual-prepare.rs')
        self.git('init', '-q'); self.git('config', 'user.name', 'Fixture'); self.git('config', 'user.email', 'fixture@example.invalid'); self.git('add', '.'); self.git('commit', '-qm', 'synthetic source')
        self.commit = self.git('rev-parse', 'HEAD').strip()
        self.input = {'schema': dual.SCHEMA, 'release': 'synthetic-not-for-release', 'source_commit': self.commit, 'networks': {}}
        self.profiles = {}
        for i, n in enumerate(dual.NETWORKS, 1):
            profile = {'profile_version': 1, 'vault_id': ('%02x' % i) * 16, 'environment': n,
                'networks': [{'chain_family': family, 'chain_id': self.registry[n][section][key], 'genesis_hash': self.registry[n][section].get('genesis_hash', '0x' + '33' * 32)} for family, section, key in [('neo-n3','neo_n3','network_magic'), ('neox','neo_x','chain_id')]],
                'custody_kms_key_arn': ARN, 'root_key_version': n + '-synthetic', 'root_key_commitment': ('%02x' % (i+10)) * 32,
                'snapshot_format_version': 2, 'signer_schema_version': 1,
                'coordinator': {'origin': 'https://authority-' + n + '.example', 'aws_region': 'us-east-1', 'snapshot_bucket': 'synthetic-bucket', 'snapshot_prefix': 'vaults/' + n, 'receipt_keys': [{'key_id':'synthetic-public-point','public_key_sec1_hex':POINT}]}, 'release_policy_version': 'synthetic-only'}
            self.profiles[n] = profile
            self.input['networks'][n] = {'profile_file': n + '.json', 'profile_sha256': '', 'workload_audience':'https://custody-' + n + '.example', 'roles': {r:n+'-'+r.lower() for r in dual.ROLES}, 'neo_n3_rpc':'https://rpc.example/'+n, 'neo_x_rpc':'https://neox.example/'+n, 'frontier_kms_key_arn': ARN, 'aws_region':'us-east-1'}
        self.write()

    def git(self, *args):
        return subprocess.check_output(['git','-C',str(self.repo),*args], stderr=subprocess.DEVNULL, env=self.env).decode()

    def write(self):
        for n, p in self.profiles.items():
            data = dual.encoded(p); (self.root / (n+'.json')).write_bytes(data)
            self.input['networks'][n]['profile_sha256'] = dual.sha(data)
        raw = dual.encoded(self.input)
        self.input_path = self.root / 'input.json'; self.input_path.write_bytes(raw)
        self.hash = dual.sha(raw)

    def validate(self):
        return dual.public_inputs(self.input_path, self.hash, self.registry)

    def stage(self, name='context'):
        return dual.stage(self.repo, self.input_path, self.hash, self.root / name, self.env)

    def enable_enrollment(self):
        profile = self.profiles['testnet']
        destination = ('environment', 'vault_id', 'networks', 'custody_kms_key_arn', 'root_key_version', 'root_key_commitment', 'coordinator')
        manifest = {k: copy.deepcopy(profile[k]) for k in destination}
        manifest.update(schema='neoos/first-admin-enrollment/v1', purpose='first-testnet-admin/v1', ceremony_id='synthetic-first-admin', caller={
            'id':'first-admin', 'label':'Test operator', 'created_at_unix':1780000000, 'token_digest':'12'*32,
            'auth_mode':'bearer', 'capabilities':['admin'], 'key_grant':'any', 'allowed_origins':[], 'disabled':False})
        raw = dual.encoded(manifest)
        (self.root/'testnet-enrollment.json').write_bytes(raw)
        self.input['networks']['testnet']['enrollment'] = {'mode':'first-testnet-admin/v1', 'manifest_file':'testnet-enrollment.json', 'manifest_sha256':dual.sha(raw)}
        profile['release_policy_version'] = dual.sha(raw)
        self.write()
        return manifest, raw

    def test_measured_enrollment_stages_exact_bytes_optin_and_profile_binding(self):
        mainnet = dual.encoded(self.profiles['mainnet'])
        _, raw = self.enable_enrollment()
        result = self.stage()
        context = self.root/'context'
        map_data = json.loads((context/'public/network-profiles.json').read_bytes())
        self.assertEqual((context/'public/custody/testnet-enrollment.json').read_bytes(), raw)
        self.assertEqual((context/'public/custody/mainnet.json').read_bytes(), mainnet)
        self.assertEqual(result['files']['public/custody/testnet-enrollment.json'], dual.sha(raw))
        self.assertEqual(map_data['testnet']['MORPHEUS_CUSTODY_ENROLLMENT_MODE'], 'first-testnet-admin/v1')
        self.assertEqual(map_data['testnet']['MORPHEUS_CUSTODY_ENROLLMENT_SHA256'], dual.sha(raw))
        self.assertEqual(map_data['testnet']['MORPHEUS_CUSTODY_ENROLLMENT_FILE'], '/app/config/custody/testnet-enrollment.json')
        self.assertFalse(any('ENROLLMENT' in k for k in map_data['mainnet']))

    def test_enrollment_file_and_claimed_digest_substitution_still_refuses(self):
        manifest, _ = self.enable_enrollment()
        manifest['caller']['id'] = 'substituted-admin'
        raw = dual.encoded(manifest)
        (self.root/'testnet-enrollment.json').write_bytes(raw)
        self.input['networks']['testnet']['enrollment']['manifest_sha256'] = dual.sha(raw)
        self.write()
        with self.assertRaisesRegex(ValueError, 'manifest/profile digest mismatch'):
            self.stage()
        self.assertFalse((self.root/'context').exists())

    def test_enrollment_negative_contract_and_mainnet_refuse(self):
        manifest, _ = self.enable_enrollment()
        for change in ('mainnet', 'sign', 'unknown', 'duplicate', 'oversize', 'bad-mode'):
            with self.subTest(change=change):
                value = copy.deepcopy(manifest)
                if change == 'mainnet': value['environment'] = 'mainnet'
                if change == 'sign': value['caller']['capabilities'] = ['admin','sign']
                if change == 'unknown': value['caller']['private_token'] = 'synthetic-disallowed'
                raw = dual.encoded(value)
                if change == 'duplicate': raw = raw.replace(b'"caller":{', b'"caller":{"id":"duplicate",', 1)
                if change == 'oversize': raw += b' ' * 16384
                (self.root/'testnet-enrollment.json').write_bytes(raw)
                self.profiles['testnet']['release_policy_version'] = dual.sha(raw)
                descriptor = self.input['networks']['testnet']['enrollment']
                descriptor['manifest_sha256'] = dual.sha(raw)
                descriptor['mode'] = 'disabled' if change == 'bad-mode' else 'first-testnet-admin/v1'
                self.write()
                with self.assertRaises(ValueError): self.validate()
        self.enable_enrollment()
        self.input['networks']['mainnet']['enrollment'] = copy.deepcopy(self.input['networks']['testnet']['enrollment'])
        self.write()
        with self.assertRaisesRegex(ValueError, 'TestNet opt-in'): self.validate()

    def test_two_exact_profiles_runtime_map_and_single_business_process(self):
        result = self.stage()
        context = self.root/'context'
        m = json.loads((context/'public/network-profiles.json').read_bytes())
        self.assertEqual(list(m), ['mainnet','testnet'])
        for n in dual.NETWORKS:
            self.assertEqual(dual.sha((context/'public/custody'/f'{n}.json').read_bytes()), self.input['networks'][n]['profile_sha256'])
            self.assertEqual(m[n]['SIGNER_SERVICE_URL'], 'http://127.0.0.1:0/'+n)
            self.assertEqual(m[n]['MORPHEUS_CUSTODY_DATA_DIR'], '/var/lib/neoos-custody/'+n)
        docker = (context/'Dockerfile').read_text()
        self.assertIn('COPY --from=rustbuild /app/config /app/config', docker)
        self.assertIn('/build/target/release/examples/dual_prepare /app/config/network-profiles.json', docker)
        self.assertIn('ENTRYPOINT ["/app/bin/nitro_init", "frontier"]', docker)
        self.assertNotIn('--bin signer_service', docker)
        self.assertNotIn('\nARG ', docker)
        self.assertIn('-path /proc -o -path /sys -o -path /dev', docker)
        self.assertIn('-prune', docker)
        self.assertNotIn('|| true', docker)
        self.assertEqual(result['git_commit'], self.commit)
        self.assertNotIn('reproducible_verified', result)

    def test_deterministic_context_and_no_ambient_secrets(self):
        with patch.dict(os.environ, {'AWS_SECRET_ACCESS_KEY':'synthetic-canary', 'SIGNER_SERVICE_TOKEN':'synthetic-canary', 'MORPHEUS_NETWORK_PROFILES_JSON':'synthetic-canary', 'DOCKER_HOST':'tcp://untrusted:1'}):
            a = self.stage('a'); b = self.stage('b')
        self.assertEqual(a,b)
        self.assertNotIn(b'synthetic-canary', b''.join(p.read_bytes() for p in (self.root/'a').rglob('*') if p.is_file()))
        self.assertNotIn('AWS_SECRET_ACCESS_KEY', self.env)
        self.assertNotIn('DOCKER_HOST', self.env)

    def test_actual_cli_rejects_unverified_and_wrong_input_digest(self):
        base=['python3',str(HERE/'build-dual-enclave.py'),'prepare','--repo',str(self.repo),'--input',str(self.input_path),'--input-sha256',self.hash,'--output',str(self.root/'out')]
        self.assertEqual(subprocess.run(base, capture_output=True, env=self.env).returncode,0)
        for argv in [base+['--allow-unverified'], base+['--no-eif'], [*base[:base.index('--input-sha256')+1], '11'*32, '--output',str(self.root/'bad')]]:
            self.assertNotEqual(subprocess.run(argv,capture_output=True,env=self.env).returncode,0)
        self.assertFalse((self.root/'bad').exists())

