        for key in ('AWS_SECRET_ACCESS_KEY','root_key','snapshot','NODE_ENV','MORPHEUS_NETWORK_PROFILES_JSON'):
            with self.subTest(key=key):
                self.input['networks']['mainnet'][key]='synthetic-canary'; self.write()
