    def test_digest_swapped_network_chain_and_genesis(self):
        original=copy.deepcopy(self.profiles)
        for field,value in [('environment','testnet'),('root_key_commitment','00'*32),('vault_id','00'*16)]:
            self.profiles=copy.deepcopy(original);self.profiles['mainnet'][field]=value;self.write()
            with self.subTest(field=field),self.assertRaises(ValueError): self.validate()
        for key,value in [('chain_id',self.registry['testnet']['neo_n3']['network_magic']),('genesis_hash','0x'+'88'*32)]:
            self.profiles=copy.deepcopy(original);self.profiles['mainnet']['networks'][0][key]=value;self.write()
            with self.subTest(key=key),self.assertRaises(ValueError): self.validate()
        self.profiles=original;self.write()
        (self.root/'mainnet.json').write_bytes((self.root/'mainnet.json').read_bytes()+b' ')
        with self.assertRaises(ValueError): self.validate()

    def test_shared_identity_root_audience_authority_snapshot_and_roles(self):
        original=copy.deepcopy(self.profiles)
        for key in ('vault_id','root_key_commitment'):
            self.profiles=copy.deepcopy(original);self.profiles['testnet'][key]=self.profiles['mainnet'][key];self.write()
            with self.subTest(key=key),self.assertRaises(ValueError):self.validate()
        for key in ('origin','snapshot_prefix'):
            self.profiles=copy.deepcopy(original);self.profiles['testnet']['coordinator'][key]=self.profiles['mainnet']['coordinator'][key];self.write()
            with self.subTest(key=key),self.assertRaises(ValueError):self.validate()
        self.profiles=original;self.write()
