    def test_path_size_link_and_fifo_inputs(self):
        alias=self.root/'alias';alias.symlink_to(self.root, target_is_directory=True)
        with self.assertRaises(ValueError):dual.regular(alias/'mainnet.json')
        self.input['networks']['mainnet']['profile_file']='../mainnet.json';self.write()
        with self.assertRaises(ValueError):self.validate()
        self.input['networks']['mainnet']['profile_file']='mainnet.json';self.write()
        p=self.root/'mainnet.json';p.unlink();p.symlink_to(self.root/'testnet.json')
        with self.assertRaises(ValueError):self.validate()
        p.unlink();p.write_bytes(b' '*65537)
        with self.assertRaises(ValueError):self.validate()
        p.unlink();os.mkfifo(p)
        with self.assertRaises(ValueError):self.validate()

    def test_source_clean_exact_and_no_private_payload(self):
        (self.repo/'untracked').write_text('x')
        with self.assertRaises(ValueError):self.stage()
        (self.repo/'untracked').unlink()
        self.input['source_commit']='11'*20;self.write()
