    def test_existing_output_never_overwritten(self):
        self.stage()
        with self.assertRaises(FileExistsError):self.stage()

    def test_replacement_source_cannot_advertise_original_commit(self):
        original = (self.repo / 'Cargo.toml').read_bytes()
        (self.repo / 'Cargo.toml').write_bytes(original + b'# unreviewed replacement\n')
        self.git('add', '.'); self.git('commit', '-qm', 'replacement fixture')
        replacement = self.git('rev-parse', 'HEAD').strip()
        # Installation/checkout intentionally use ordinary Git replacement semantics.
        env = {k:v for k,v in self.env.items() if k not in ('GIT_NO_REPLACE_OBJECTS', 'GIT_GRAFT_FILE')}
        for args in [('replace', self.commit, replacement), ('checkout', '--detach', self.commit)]:
            subprocess.run(['git', '-C', str(self.repo), *args], env=env, check=True, capture_output=True)
        with self.assertRaises(ValueError): self.stage()
        self.assertFalse((self.root / 'context').exists())

    def test_replacement_and_legacy_grafts_cannot_invent_canonical_ancestry(self):
        tip = self.commit
        tree = self.git('rev-parse', tip + '^{tree}').strip()
        unrelated = self.git('commit-tree', tree, '-m', 'disjoint fixture').strip()
        self.git('remote', 'add', 'origin', dual.ORIGIN)
        real_git = dual.git
        def recorded(repo, env, *args):
            if args[0] == 'ls-remote': return (tip + '\trefs/heads/main\n').encode()
            return real_git(repo, env, *args)
        for kind in ('replace', 'legacy'):
            with self.subTest(kind=kind):
                if kind == 'replace': self.git('replace', '--graft', tip, unrelated)
                else:
                    self.git('replace', '-d', tip)
                    (self.repo / '.git/info/grafts').write_text(tip + ' ' + unrelated + '\n')
                with patch.object(dual, 'git', recorded):
                    self.assertEqual(dual.canonical(self.repo, tip, self.env), tip)
                    with self.assertRaises(ValueError): dual.canonical(self.repo, unrelated, self.env)

    def test_cli_output_aliases_refused_with_outside_positive(self):
        alias = self.root / 'alias'; alias.symlink_to(self.repo, target_is_directory=True)
        (self.root / 'away').mkdir()
        for output in (alias / 'escaped', self.root / 'away/../source/escaped', self.repo / 'escaped'):
            with self.subTest(output=str(output)):
                command = ['python3', '-B', str(HERE / 'build-dual-enclave.py'), 'prepare', '--repo', str(self.repo), '--input', str(self.input_path), '--input-sha256', self.hash, '--output', str(output)]
                try:
                    self.assertNotEqual(subprocess.run(command, env=self.env, capture_output=True, timeout=20).returncode, 0)
                    self.assertFalse((self.repo / 'escaped').exists())
                finally:
                    if (self.repo / 'escaped').exists(): shutil.rmtree(self.repo / 'escaped')
        self.assertEqual(self.stage('outside')['git_commit'], self.commit)

    def test_output_parent_replacement_does_not_redirect_writes(self):
        parent = self.root / 'output-parent'; parent.mkdir()
        moved = self.root / 'parked-parent'
        real_inputs = dual.public_inputs
        def swap(*args):
            result = real_inputs(*args)
            parent.rename(moved); parent.symlink_to(self.repo, target_is_directory=True)
            return result
        with patch.object(dual, 'public_inputs', swap):
            with self.assertRaises((ValueError, OSError)):
                dual.stage(self.repo, self.input_path, self.hash, parent / 'escaped', self.env)
        self.assertFalse((self.repo / 'escaped').exists())
        self.assertEqual(list(moved.iterdir()), [])

    def test_publication_failure_leaves_no_final_or_staging_directory(self):
        real_path_write, real_write = Path.write_bytes, os.write
        def selected(data): return b'"schema":"neoos/dual-image-build-evidence/v1"' in bytes(data)
        def path_failure(path, data):
            if path.name == 'build-evidence.json':
                real_path_write(path, data[:23]); raise OSError(errno.ENOSPC, 'synthetic ENOSPC')
            return real_path_write(path, data)
        def fd_failure(fd, data):
            if selected(data):
                real_write(fd, data[:23]); raise OSError(errno.ENOSPC, 'synthetic ENOSPC')
            return real_write(fd, data)
        with patch.object(Path, 'write_bytes', path_failure), patch.object(os, 'write', fd_failure):
            with self.assertRaises(OSError) as failure: self.simulate()
        self.assertEqual(failure.exception.errno, errno.ENOSPC)
        self.assertFalse((self.root / 'result').exists())
        self.assertFalse(list(self.root.glob('.dual-publish-*')))
        for p in list(self.root.iterdir()):
            if p.name.startswith(('context', 'image-config', 'nitro-artifacts', 'build-')):
                shutil.rmtree(p) if p.is_dir() else p.unlink()
        result, _ = self.simulate()
        self.assertEqual(result['builds'][0]['eif_sha256'], dual.sha((self.root / 'result/enclave.eif').read_bytes()))

