    def test_cli_sigterm_unwinds_owned_command(self):
        started, finished = self.root / 'cancel-started', self.root / 'cancel-finished'
        child = 'import time;from pathlib import Path;Path(%r).touch();time.sleep(1.2);Path(%r).touch()' % (str(started), str(finished))
        driver = ("import importlib.util,sys;spec=importlib.util.spec_from_file_location('dual',%r);m=importlib.util.module_from_spec(spec);spec.loader.exec_module(m);" % str(HERE / 'build-dual-enclave.py'))
        driver += "original=m.public_inputs\ndef delayed(*args):\n m.run(['/usr/bin/python3','-c',%r],m.safe_env(%r),timeout=10)\n return original(*args)\nm.public_inputs=delayed\n" % (child, self.root)
        # Path repr is not an executable fixture; use a literal Path construction.
        driver = driver.replace(repr(self.root), "__import__('pathlib').Path(%r)" % str(self.root))
        driver += 'sys.argv=%r\nm.main()\n' % ['dual', 'prepare', '--repo', str(self.repo), '--input', str(self.input_path), '--input-sha256', self.hash, '--output', str(self.root / 'cancel-output')]
        process = subprocess.Popen(['/usr/bin/python3', '-c', driver], env=self.env, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
        try:
            deadline = time.monotonic() + 5
            while not started.exists() and time.monotonic() < deadline and process.poll() is None: time.sleep(0.02)
            self.assertTrue(started.exists())
            process.send_signal(signal.SIGTERM)
            process.communicate(timeout=5)
            time.sleep(1.3)
            self.assertFalse(finished.exists(), 'CLI cancellation left owned command running')
            self.assertFalse((self.root / 'cancel-output').exists())
            self.assertFalse(list(self.root.glob('.dual-publish-*')))
        finally:
            if process.poll() is None: process.kill(); process.communicate(timeout=5)

