    def simulate(self, fault=None, observe=None):
        manifest=self.stage();context=self.root/'context';calls=[];counter=0;self.calls=calls;containers={}
        def fake(args,env,cwd=None,timeout=120):
            nonlocal counter
            calls.append([str(a) for a in args]);a=[str(x) for x in args]
            self.assertNotIn('AWS_SECRET_ACCESS_KEY',env)
            if observe is not None: observe(a)
            if 'build' in a and 'docker' in a[0]:
                self.assertIn('--no-cache',a);self.assertIn('--platform=linux/amd64',a)
                self.assertNotIn('--build-arg',a);counter+=1
                if fault == 'timeout': raise subprocess.TimeoutExpired(a, 0.1)
                return b''
            if '{{.Id}}' in a:return ('sha256:'+'ab'*32).encode()
            if a[3:4] == ['create']:
                cid=str(counter)*64
                label=a[a.index('--label')+1].split('=',1)
                containers[cid]={'Id':cid,'Name':'/'+a[a.index('--name')+1], 'Image':a[-1], 'Config':{'Labels':dict([label])}}
                return cid.encode()
            if a[3:5] == ['container','ls']:
                name=a[a.index('--filter')+1].split('=',1)[1]
                return '\n'.join(cid for cid,item in containers.items() if name in item['Name']).encode()
            if a[3:5] == ['container','inspect']:return dual.encoded([containers[a[-1]]])
            if a[3:4] == ['rm']:containers.pop(a[-1]);return b''
            if 'cp' in a:
                out=Path(a[-1]);shutil.copytree(context/'public',out)
                receipt={'schema':'neoos/dual-custody-build/v1','networks':list(dual.NETWORKS),'map_sha256':manifest['map_sha256']}
                if fault=='receipt':receipt['map_sha256']='99'*32
                (out/'custody-build-validation.json').write_bytes(dual.encoded(receipt))
                if fault=='payload':(out/'custody/testnet.json').write_text('{}')
                if fault=='enrollment':(out/'custody/testnet-enrollment.json').write_text('{}')
                return b''
            if '{{json .Config.Env}}' in a:
                m=(context/'public/network-profiles.json').read_text().strip()
                if fault=='runtime-map':m='{}'
                return dual.encoded(['NODE_ENV=production','MORPHEUS_ATTESTED_BOOT=require','MORPHEUS_ALLOW_EPHEMERAL_KEY=0','MORPHEUS_NETWORK_PROFILES_JSON='+m])
            if 'build-enclave' in a or 'describe-eif' in a:
                if 'build-enclave' in a:Path(a[-1]).write_bytes(b'synthetic EIF control '+str(counter).encode())
                v='22' if (fault=='repro' and counter==2) or (fault=='readback' and 'describe-eif' in a) else '11'
                p={'HashAlgorithm':'SHA384',**{k:v*48 for k in ('PCR0','PCR1','PCR2')}}
                if fault=='empty':p.pop('PCR2')
                if fault=='zero':p['PCR0']='00'*48
                return dual.encoded({'Measurements':p})
            return b''
        with patch.object(dual,'canonical',return_value=self.commit),patch.object(dual,'run',fake):
            result=dual.build(self.repo,context,manifest,self.root/'result',self.env,Path('/fake/docker'),Path('/fake/nitro-cli'),Path('/fake/blobs'))
        return result,calls

    def test_enrollment_exported_bytes_are_verified_before_publication(self):
        self.enable_enrollment()
        result, _ = self.simulate()
        self.assertIn('public/custody/testnet-enrollment.json', result['files'])

    def test_enrollment_export_substitution_refuses_publication(self):
        self.enable_enrollment()
        with self.assertRaisesRegex(ValueError, 'image enrollment digest mismatch'):
            self.simulate('enrollment')
        self.assertFalse((self.root/'result').exists())

    def test_two_uncached_builds_measure_readback_and_publish_first(self):
        result,calls=self.simulate()
        self.assertEqual(len(result['builds']),2)
        self.assertEqual((self.root/'result/enclave.eif').read_bytes(),b'synthetic EIF control 1')
        self.assertTrue(result['reproducible_verified'])
        self.assertEqual(len([a for a in calls if 'build-enclave' in a]),2)
        self.assertEqual(len([a for a in calls if 'describe-eif' in a]),2)

    def test_adversarial_build_receipt_payload_map_measurements(self):
        for fault in ('receipt','payload','runtime-map','repro','readback','empty','zero'):
            with self.subTest(fault=fault):
                with self.assertRaises(ValueError):self.simulate(fault)
                self.assertFalse((self.root/'result').exists())
                for p in list(self.root.iterdir()):
                    if p.name.startswith(('context','image-config','nitro-artifacts','build-')):
                        shutil.rmtree(p) if p.is_dir() else p.unlink()


